/*
 * A079686  Start with 0; at n-th step, write down what is in the sequence so
 *          far.
 * https://oeis.org/A079686
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, base
 * Formula:   a(n) is generated by an inventory process. Starting with [0], at
 *            each step append for each integer from the current maximum down
 *            to 0: the count of that integer followed by the integer itself
 * Range:     u8 n <= 9068, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>

seq_t a(idx_t n)
{
    /* static state for memoisation */
    static seq_t *seq = NULL;
    static size_t seq_len = 0, seq_cap = 0;
    static idx_t *freq = NULL;
    static size_t freq_len = 0;
    static idx_t max_val = 0;

    /* initialisation */
    if (seq == NULL) {
        /* initial capacity for sequence */
        seq_cap = 4;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        if (!seq) return (seq_t)0;   /* allocation failure */

        /* first term 0 */
        seq[0] = (seq_t)0;
        seq_len = 1;

        /* frequency array: at least one element */
        freq_len = 1;
        freq = (idx_t *)malloc(freq_len * sizeof(idx_t));
        if (!freq) return (seq_t)0;   /* allocation failure */
        memset(freq, 0, freq_len * sizeof(idx_t));
        freq[0] = (idx_t)1;   /* one zero initially */
        max_val = 0;
    }

    /* if already computed, return */
    if (n < seq_len) return seq[n];

    /* generate sequence until we have at least n+1 terms */
    while (seq_len <= n) {
        /* block size = 2 * (max_val + 1) */
        size_t block_size = 2 * ((size_t)max_val + 1);

        /* ensure capacity for new block */
        if (seq_cap - seq_len < block_size) {
            size_t new_cap = seq_cap ? seq_cap : 4;
            while (new_cap - seq_len < block_size)
                new_cap *= 2;
            seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
            if (!tmp) return (seq_t)0;   /* allocation failure */
            seq = tmp;
            seq_cap = new_cap;
        }

        size_t before = seq_len;

        /* create the block using the current frequencies (snapshot) */
        for (idx_t v = max_val; ; --v) {
            /* freq[v] is valid because freq_len >= max_val+1 */
            seq[seq_len++] = (seq_t)(freq[v]);
            seq[seq_len++] = (seq_t)v;
            if (v == 0) break;   /* unsigned loop terminates safely */
        }

        /* update frequencies with the newly appended values */
        for (size_t i = before; i < seq_len; ++i) {
            seq_t val = seq[i];
            idx_t id = (idx_t)val;

            if (id >= (idx_t)freq_len) {
                size_t new_len = (size_t)(id + 1);
                idx_t *tmp = (idx_t *)realloc(freq, new_len * sizeof(idx_t));
                if (!tmp) return (seq_t)0;   /* allocation failure */
                /* initialise new slots to zero */
                memset(tmp + freq_len, 0, (new_len - freq_len) * sizeof(idx_t));
                freq = tmp;
                freq_len = new_len;
            }
            ++freq[id];
            if (id > max_val) max_val = id;
        }
    }

    return seq[n];
}
